// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TunerHost) predicate.TunerHost {
	return predicate.TunerHost(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TunerHost) predicate.TunerHost {
	return predicate.TunerHost(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TunerHost) predicate.TunerHost {
	return predicate.TunerHost(sql.NotPredicates(p))
}





